WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_x_multiple'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '年龄与倍数综合', 'kp-age-x-multiple', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "年龄与倍数极限拉扯"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心策略：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "极限代入法。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、实战心法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题的选项通常是 4 个相邻很近的整数。别列大方程，直接选 C 选项代入，大了就选小一点的，小了就选大一点的。15 秒内结束战斗。"}]}]}$$ AS jsonb), NULL, '年龄与倍数综合的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "年龄与倍数综合"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_x_multiple", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
